1	type Item = { type: string; cursed?: boolean; enchantment?: number };
2	
3	const basePremiumsByType: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };
4	
5	const BLOCK_SIZE = 3;
6	const BLOCK_PREMIUM = 60;
7	
8	const sumOverItems = (items: Item[], perItem: (item: Item) => number): number =>
9	  items.reduce((sum, item) => sum + perItem(item), 0);
10	
11	const basePremiumForItem = (item: Item): number => basePremiumsByType[item.type];
12	
13	const sumOfItemBasePremiums = (items: Item[]): number =>
14	  sumOverItems(items, basePremiumForItem);
15	
16	const groupByType = (items: Item[]): Item[][] => {
17	  const groups = new Map<string, Item[]>();
18	  for (const item of items) {
19	    const group = groups.get(item.type) ?? [];
20	    group.push(item);
21	    groups.set(item.type, group);
22	  }
23	  return [...groups.values()];
24	};
25	
26	const basePremiumForGroup = (group: Item[]): number =>
27	  group.length === BLOCK_SIZE ? BLOCK_PREMIUM : sumOfItemBasePremiums(group);
28	
29	export const basePremium = (items: Item[]): number =>
30	  groupByType(items).reduce((sum, group) => sum + basePremiumForGroup(group), 0);
31	
32	const PROCESSING_FEE = 5;
33	
34	type Customer = { yearsWithMHPCO: number };
35	type QuoteStep = { op: "quote"; items: Item[] };
36	type Scenario = { customer: Customer; steps: QuoteStep[] };
37	
38	const CURSE_SURCHARGE_RATE = 0.5;
39	const HIGH_ENCHANTMENT_RATE = 0.3;
40	const HIGH_ENCHANTMENT_THRESHOLD = 5;
41	const FIRST_INSURANCE_RATE = 0.1;
42	const LOYALTY_RATE = 0.2;
43	const LOYALTY_THRESHOLD = 2;
44	const FOLLOWUP_RATE = 0.15;
45	
46	const surchargeOf = (item: Item, rate: number): number => basePremiumForItem(item) * rate;
47	
48	const curseSurchargeForItem = (item: Item): number =>
49	  item.cursed ? surchargeOf(item, CURSE_SURCHARGE_RATE) : 0;
50	
51	const curseSurcharge = (items: Item[]): number =>
52	  sumOverItems(items, curseSurchargeForItem);
53	
54	const highEnchantmentSurchargeForItem = (item: Item): number =>
55	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
56	    ? surchargeOf(item, HIGH_ENCHANTMENT_RATE)
57	    : 0;
58	
59	const highEnchantmentSurcharge = (items: Item[]): number =>
60	  sumOverItems(items, highEnchantmentSurchargeForItem);
61	
62	const rateOfPolicyBase = (policyBase: number, rate: number): number => policyBase * rate;
63	
64	const firstInsuranceSurcharge = (policyBase: number): number =>
65	  rateOfPolicyBase(policyBase, FIRST_INSURANCE_RATE);
66	
67	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
68	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD ? rateOfPolicyBase(policyBase, LOYALTY_RATE) : 0;
69	
70	const followUpDiscount = (policyBase: number, isFollowUp: boolean): number =>
71	  isFollowUp ? rateOfPolicyBase(policyBase, FOLLOWUP_RATE) : 0;
72	
73	const itemSurcharges = (items: Item[]): number =>
74	  curseSurcharge(items) + highEnchantmentSurcharge(items);
75	
76	const quotePremium = (step: QuoteStep, customer: Customer, isFollowUp: boolean): number => {
77	  const policyBase = basePremium(step.items);
78	  const surcharges = itemSurcharges(step.items) + firstInsuranceSurcharge(policyBase);
79	  const discounts = loyaltyDiscount(policyBase, customer) + followUpDiscount(policyBase, isFollowUp);
80	  return Math.ceil(policyBase + surcharges - discounts + PROCESSING_FEE);
81	};
82	
83	export const runScenario = (scenario: Scenario): { results: { premium: number }[] } => ({
84	  results: scenario.steps.map((step, index) => ({
85	    premium: quotePremium(step, scenario.customer, index > 0),
86	  })),
87	});
